JS = SE_JS + "var tb=document.querySelectorAll('[data-theme-set]');function th(v,save){var r=document.documentElement;if(v==='auto')delete r.dataset.theme;else r.dataset.theme=v;tb.forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.themeSet===v));});if(save){try{localStorage.setItem('crypt-theme',v);}catch(e){}}}th(document.documentElement.dataset.theme||'auto',false);tb.forEach(function(b){b.addEventListener('click',function(){th(b.dataset.themeSet,true);});});var sd=document.getElementById('side');document.getElementById('menubtn').addEventListener('click',function(){window.cse(1568,1568,.035,'square',.05);if(sd.showModal)sd.showModal();else sd.setAttribute('open','');});function sc(){if(sd.close)sd.close();else sd.removeAttribute('open');}document.getElementById('sideclose').addEventListener('click',sc);sd.addEventListener('click',function(ev){if(ev.target!==sd)return;var r=sd.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)sc();});"

def two(s):
    """'Cryptiana（S. Tomokiyo）' / 'cyphersolver (Bourdeau)' -> the name, with the bracketed part as a small second line."""
    m = re.match(r'(.+?)\s*[（(](.+)[）)]\s*$', s)
    return f'<span class="nm">{m.group(1)}</span><span class="sub">{m.group(2)}</span>' if m else s

def drawer(T, links, title=('メニュー', 'Menu')):
    """links: [(href, ja, en)] shown under 情報 / Info."""
    lis = ''.join(f'<li><a href="{h}"{' class="gh"' if 'github.com' in h else ''}>{T(two(ja), two(en))}</a></li>' for h, ja, en in links)
    return (f'<dialog class="side" id="side" aria-label="メニュー / Menu"><div class="advh"><b>{T(*title)}</b>' + LANGHEAD +
            '<button type="button" class="advx" id="sideclose" aria-label="閉じる / Close">×</button></div>'
            + f'<section><ul class="navl">{lis}</ul></section>' + THEME + '</dialog>')

TAGLINE = ('未解決暗号の<wbr>オープン<wbr>検索エンジン', 'open search engine for unsolved historical ciphers')
def cbar(BAR, T):
    """Header for Cryptoole pages: logo (links to the search top) and tagline at the top left, then language toggle and ☰."""
    bar = re.sub(r'<button type="button" class="menub".*?</button>', '', BAR, flags=re.S)
    bar = re.sub(r'<span class="ctag">(?:<span[^>]*>(?:[^<]|<wbr>)*</span>)*</span>', '', bar)   # idempotent
    bar = re.sub(r'<a class="brand[^"]*"[^>]*>.*?</a></span>|<a class="brand[^"]*"[^>]*>.*?</a>', f'<a class="brand clogo" href="./" title="Cryptoole">{EMBLEM}<span class="lgt" data-t="Cryptoole">{LOGO_HTML}</span></a><span class="ctag">{T(*TAGLINE)}</span>', bar, count=1, flags=re.S)
    bar = re.sub(r'<div class="toggle" role="group" aria-label="Language">.*?</div>', '', bar, flags=re.S)   # language lives in the menu
    return bar.replace('</header>', '<span class="bsp"></span>' + MENUB + '</header>')
